const trimNotices = `-- name: TrimNotices :execrows
DELETE FROM notices
WHERE cursor <= COALESCE((SELECT n.cursor FROM notices n ORDER BY n.cursor DESC LIMIT 1 OFFSET ?), 0)
`

// Keep the newest :keep notices. The high-water marks are separate, so this
// never lets an old transition notify again.
func (q *Queries) TrimNotices(ctx context.Context, offset int64) (int64, error) {
	result, err := q.db.ExecContext(ctx, trimNotices, offset)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

