const upsertNoticeHighWater = `-- name: UpsertNoticeHighWater :execrows
INSERT INTO notice_high_water (task_id, source_kind, source_run, revision, updated_at)
VALUES (?, ?, ?, ?, ?)
ON CONFLICT (task_id, source_kind, source_run) DO UPDATE
SET revision = excluded.revision, updated_at = excluded.updated_at
WHERE excluded.revision > notice_high_water.revision
`

type UpsertNoticeHighWaterParams struct {
	TaskID     string
	SourceKind string
	SourceRun  string
	Revision   int64
	UpdatedAt  string
}

func (q *Queries) UpsertNoticeHighWater(ctx context.Context, arg UpsertNoticeHighWaterParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, upsertNoticeHighWater,
		arg.TaskID,
		arg.SourceKind,
		arg.SourceRun,
		arg.Revision,
		arg.UpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
